// A density curve over [lo, hi], plus the shaded rejection region(s): each
// entry of `tails` is an [from, to] interval.
function rejectionFigure(pdf, lo, hi, tails, criticalValues) {
  const xs = [], ys = []
  for (let i = 0; i &lt;= 500; i++) {
    const x = lo + (hi - lo) * i / 500
    xs.push(x)
    ys.push(pdf(x))
  }
  const traces = []
  for (const [from, to] of tails) {
    const tx = [], ty = []
    for (let i = 0; i &lt;= 200; i++) {
      const x = from + (to - from) * i / 200
      tx.push(x)
      ty.push(pdf(x))
    }
    traces.push({x: tx, y: ty, type: "scatter", mode: "lines", fill: "tozeroy", line: {width: 0},
      fillcolor: VM.plotting.alpha(chartColors.fn, 0.45), hoverinfo: "skip", name: "Rejection region"})
  }
  traces.push({x: xs, y: ys, type: "scatter", mode: "lines", line: {color: chartColors.alt, width: 2}, name: "pdf"})
  const shapes = []
  for (const c of criticalValues) {
    shapes.push({type: "line", x0: c, x1: c, yref: "paper", y0: 0, y1: 1, line: {color: chartColors.ok, dash: "dash", width: 2}})
  }
  return {traces, shapes}
}



















































