// Triangular density on [a, b] with mode c.
function triangularPdf(x, a, b, c) {
  if (a &lt;= x && x &lt; c) return 2 * (x - a) / ((b - a) * (c - a))
  if (c &lt;= x && x &lt;= b) return 2 * (b - x) / ((b - a) * (b - c))
  return 0
}





































