  const mu1 = -2, sd1 = 1, mu2 = 2, sd2 = 0.5
  // The linear combination w1 X + w2 Y is normal with mean w1 mu1 + w2 mu2
  // and variance w1² sd1² + w2² sd2².
  const combMean = w1 * mu1 + w2 * mu2
  const combVar = w1 * w1 * sd1 * sd1 + w2 * w2 * sd2 * sd2
  const xs = [], mixture = [], combination = []
