// Joint exponential: f(x, y) = c exp(-lambda x y) on [0, D1] x [0, D2].
g2Lambda = 2
g2D1 = 5
g2D2 = 3
g2N = 10000

// Unnormalized: the contour and surface plots only need the shape.
function g2ExpDensity(x, y) {
  if (x &lt; 0 || x &gt; g2D1 || y &lt; 0 || y &gt; g2D2) return 0
  return Math.exp(-g2Lambda * x * y)
}

// One draw from Exp(rate) truncated to [0, D], by the inverse transform
// X = -log(1 - U (1 - e^{-rate D})) / rate. At rate 0 it is uniform.
function g2TruncatedExponential(rate, D, u) {
  if (rate === 0) return D * u
  return -Math.log(1 - u * (1 - Math.exp(-rate * D))) / rate
}

// A density on a grid, for Plotly's contour and surface traces.
function g2Grid(density, lo, hi, count) {
  const xs = [], z = []
  for (let i = 0; i &lt; count; i++) xs.push(lo + (hi - lo) * i / (count - 1))
  for (const y of xs) {
    const row = []
    for (const x of xs) row.push(density(x, y))
    z.push(row)
  }
  return {x: xs, y: xs, z}
}

