// The first k sweeps as a staircase: a horizontal move to the new X, then a
// vertical move to the new Y. Later sweeps are drawn more opaque.
function g2Path(plot, chain, k, title) {
  const traces = []
  for (let i = 1; i &lt;= k; i++) {
    const opacity = Math.log(1 + i / k) / Math.log(2)
    traces.push({x: [chain.x[i - 1], chain.x[i], chain.x[i]], y: [chain.y[i - 1], chain.y[i - 1], chain.y[i]],
      type: "scatter", mode: "lines", line: {color: chartColors.fn, width: 1.5}, opacity, showlegend: false, hoverinfo: "skip"})
  }
  traces.push({x: chain.x.slice(0, k + 1), y: chain.y.slice(0, k + 1), type: "scatter", mode: "markers",
    marker: {color: chartColors.alt, size: 5}, name: "Samples"})
  traces.push({x: [chain.x[0]], y: [chain.y[0]], type: "scatter", mode: "markers",
    marker: {color: chartColors.ok, size: 12}, name: "Start"})
  traces.push({x: [chain.x[k]], y: [chain.y[k]], type: "scatter", mode: "markers",
    marker: {color: chartColors.fn, size: 12}, name: `${k}-th sample`})
  return VM.plotting.plotWithLegend(plot, traces, {title: {text: title}, margin: {t: 40}, xaxis: {title: "X"}, yaxis: {title: "Y"}})
}
