// Gibbs sampler for the joint exponential, from (X0, Y0) = (1, 1):
// X_i ~ Exp(lambda Y_{i-1}) on [0, D1], then Y_i ~ Exp(lambda X_i) on [0, D2].
g2ExpChain = {
  const rng = VM.sampling.seededRandom(0)
  const x = [1], y = [1]
  for (let i = 0; i &lt; g2N; i++) {
    const nextX = g2TruncatedExponential(g2Lambda * y[i], g2D1, rng())
    x.push(nextX)
    y.push(g2TruncatedExponential(g2Lambda * nextX, g2D2, rng()))
  }
  return {x, y}
}
