gibbsView = {
  const n = gibbsN
  const xs = gibbsChain.x.slice(1, n + 1)
  const ys = gibbsChain.y.slice(1, n + 1)
  let mx = 0, my = 0
  for (let i = 0; i &lt; n; i++) {
    mx += xs[i]
    my += ys[i]
  }
  mx /= n
  my /= n
  let sxy = 0, sxx = 0, syy = 0
  for (let i = 0; i &lt; n; i++) {
    sxy += (xs[i] - mx) * (ys[i] - my)
    sxx += (xs[i] - mx) * (xs[i] - mx)
    syy += (ys[i] - my) * (ys[i] - my)
  }
  let corr = NaN
  if (sxx &gt; 0 && syy &gt; 0) corr = sxy / Math.sqrt(sxx * syy)
  return {n, xs, ys, mx, my, corr}
}







