      logDensity: p =&gt; (mhLRegion.inside(p[0], p[1]) ? 0 : -Infinity),
      start: mhLRegion.start,
      n: 10000,
      scale: sigma,
      proposal: "gaussian",
      rng: VM.sampling.seededRandom(0)
    })
    runs.push({sigma, chain})
  }
  return runs
}

function mhLSampleFigure(plot, run) {
  const xs = [], ys = []
  for (const p of run.chain.samples) {
    xs.push(p[0])
    ys.push(p[1])
