  }
  const left = circle(-1, 0, 1)
  const right = circle(1, 0, 1)
  return new Map([
    ["L-shape", {
      inside: (x, y) =&gt; (x &gt;= 0 && x &lt;= 1 && y &gt;= 0 && y &lt;= 0.1) || (x &gt;= 0 && x &lt;= 0.1 && y &gt;= 0 && y &lt;= 1),
