// B bootstrap replicates of statistic(resample), each resample drawn from
// `data` with replacement.
function bsBootstrap(data, statistic, B, rng) {
  const out = []
  const n = data.length
  for (let b = 0; b &lt; B; b++) {
    const resample = []
    for (let i = 0; i &lt; n; i++) resample.push(data[Math.floor(rng() * n)])
    out.push(statistic(resample))
  }
  return out
}

