18.4 Particle Filter Implementation
The following implementation demonstrates a complete particle filter for 2D object tracking. The demonstration tracks an object moving in 2D space with:

Process noise: Models random accelerations (\(\sigma_a = 0.5\))
Observation noise: GPS-like position measurements (\(\sigma_r = 1.0\))
Particles: 500 particles provide good approximation quality
Duration: 30 time steps with unit time intervals

The visualization shows the particle filter’s ability to track the true trajectory despite noisy observations, with automatic resampling maintaining particle diversity throughout the simulation.

VM = window.VM
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)

// A constant-velocity model in 2-D: state [x, y, vx, vy], dt = 1. The
// process noise is a random acceleration a ~ N(0, sigma_a²) per axis, which
// moves the position by a dt²/2 and the velocity by a dt -- exactly the
// covariance Q = sigma_a² [[dt⁴/4, dt³/2], [dt³/2, dt²]] per axis.
// Observations are the position plus N(0, sigma_r² I) noise.
pfModel = ({dt: 1, T: 30, nParticles: 500, sigmaA: 0.5, sigmaR: 1.0, start: [0, 0, 1, 0.5], initialVariances: [2, 2, 1, 1]})

function pfPropagate(state, dt, sigmaA, gaussian) {
  const ax = sigmaA * gaussian()
  const ay = sigmaA * gaussian()
  return [
    state[0] + dt * state[2] + ax * dt * dt / 2,
    state[1] + dt * state[3] + ay * dt * dt / 2,
    state[2] + ax * dt,
    state[3] + ay * dt
  ]
}

// Simulate the truth and the observations, then run the bootstrap particle
// filter: propagate, weight by the observation likelihood, resample
// (systematically) when the effective sample size falls below N/2.
pfRun = {
  const m = pfModel
  const rng = VM.sampling.seededRandom(42)
  const gaussian = VM.sampling.gaussianRandom(rng)

  const truth = [m.start]
  const observations = []
  for (let t = 0; t &lt; m.T; t++) {
    const next = pfPropagate(truth[t], m.dt, m.sigmaA, gaussian)
    truth.push(next)
    observations.push([next[0] + m.sigmaR * gaussian(), next[1] + m.sigmaR * gaussian()])
  }

  let particles = []
  for (let i = 0; i &lt; m.nParticles; i++) {
    const p = []
    for (let k = 0; k &lt; 4; k++) p.push(m.start[k] + Math.sqrt(m.initialVariances[k]) * gaussian())
    particles.push(p)
  }
  let weights = new Array(m.nParticles).fill(1 / m.nParticles)

  const estimates = [], positionCovs = [], ess = [], resampledSteps = []
  for (let t = 0; t &lt; m.T; t++) {
    // Predict.
    for (let i = 0; i &lt; m.nParticles; i++) particles[i] = pfPropagate(particles[i], m.dt, m.sigmaA, gaussian)
    // Update: w_i *= p(y_t | x_t^(i)); the Gaussian's constant cancels on normalizing.
    let total = 0
    for (let i = 0; i &lt; m.nParticles; i++) {
      const dx = observations[t][0] - particles[i][0]
      const dy = observations[t][1] - particles[i][1]
      weights[i] *= Math.exp(-(dx * dx + dy * dy) / (2 * m.sigmaR * m.sigmaR))
      total += weights[i]
    }
    let sumSquares = 0
    for (let i = 0; i &lt; m.nParticles; i++) {
      weights[i] /= total
      sumSquares += weights[i] * weights[i]
    }
    // Weighted mean and position covariance, before any resampling.
    const mean = [0, 0, 0, 0]
    for (let i = 0; i &lt; m.nParticles; i++) {
      for (let k = 0; k &lt; 4; k++) mean[k] += weights[i] * particles[i][k]
    }
    let cxx = 0, cxy = 0, cyy = 0
    for (let i = 0; i &lt; m.nParticles; i++) {
      const dx = particles[i][0] - mean[0]
      const dy = particles[i][1] - mean[1]
      cxx += weights[i] * dx * dx
      cxy += weights[i] * dx * dy
      cyy += weights[i] * dy * dy
    }
    estimates.push(mean)
    positionCovs.push([cxx, cxy, cyy])
    // Resample when the effective sample size 1 / sum w² drops below N/2.
    const nEff = 1 / sumSquares
    ess.push(nEff)
    if (nEff &lt; m.nParticles / 2) {
      const indices = VM.filters.systematicResample(weights, rng())
      const resampled = []
      for (const j of indices) resampled.push(particles[j].slice())
      particles = resampled
      weights = new Array(m.nParticles).fill(1 / m.nParticles)
      resampledSteps.push(t)
    }
  }

  const errors = []
  for (let t = 0; t &lt; m.T; t++) {
    const dx = estimates[t][0] - truth[t + 1][0]
    const dy = estimates[t][1] - truth[t + 1][1]
    errors.push(Math.sqrt(dx * dx + dy * dy))
  }
  return {truth, observations, estimates, positionCovs, ess, resampledSteps, errors}
}












































