// Everything that depends on the graph alone: layout, transition matrix,
// stationary distribution and spectrum. Rerun only when the graph or the
// lazy toggle changes, not on every time step.
walkGraph = {
  const g = walkGraphs.get(walkGraphName)
  const {P, degrees, stationary} = VM.discreteMath.randomWalkMatrix(g.nodeCount, g.edges, {lazy: walkLazy})
  const positions = VM.discreteMath.springLayout(g.nodeCount, g.edges, {seed: 42, iterations: 400})

  // P = D^-1 A is not symmetric, but D^(1/2) P D^(-1/2) is, and has the
  // same eigenvalues -- which is what lets a symmetric solver find them.
  const S = []
  for (let i = 0; i &lt; g.nodeCount; i++) {
    const row = []
    for (let j = 0; j &lt; g.nodeCount; j++) row.push(Math.sqrt(degrees[i] / degrees[j]) * P[i][j])
    S.push(row)
  }
  const eigenvalues = VM.numerical.symmetricEigenvalues(S)
  return {...g, P, stationary, positions, eigenvalues}
}







// pi_t for t = 0..walkMaxTime from the chosen start, with its distance to
// stationarity at every step.
walkRun = {
  const p0 = new Array(walkGraph.nodeCount).fill(0)
  p0[walkStart] = 1
  const distributions = VM.mcmc.evolveDistribution(walkGraph.P, p0, walkMaxTime)
  const tv = []
  for (const p of distributions) tv.push(VM.mcmc.totalVariation(p, walkGraph.stationary))
  // First time the distance drops to the threshold and stays there.
  let mixingTime = null
  for (let t = walkMaxTime; t &gt;= 0; t--) {
    if (tv[t] &gt; walkThreshold) break
    mixingTime = t
  }
  return {distributions, tv, mixingTime}
}







