// A simple random walk on the 15-cycle: 5000 steps from vertex 0, each
// step to one of the two neighbours with probability 1/2.
mcCycleN = 15
mcWalk = {
  const rng = VM.sampling.seededRandom(3)
  const walk = [0]
  for (let i = 0; i &lt; 5000; i++) {
    let step = 1
    if (rng() &lt; 0.5) step = -1
    walk.push((walk[i] + step + mcCycleN) % mcCycleN)
  }
  return walk
}

// Fraction of time spent at each vertex.
function mcVisitFrequencies(walk) {
  const counts = new Array(mcCycleN).fill(0)
  for (const v of walk) counts[v] += 1
  const out = []
  for (const c of counts) out.push(c / walk.length)
  return out
}

