      textfont: {color: chartColors.ink}, marker: {size: 26, color: VM.plotting.alpha(chartColors.fn, 0.3), line: {color: chartColors.fn, width: 1}}}
  ], {title: {text: `Generating 5000 samples on the ${mcCycleN}-cycle`}, margin: {t: 40}, showlegend: false,
    xaxis: {...hidden, range: [-1.25, 1.25]}, yaxis: {...hidden, range: [-1.25, 1.25], scaleanchor: "x"}})
}






mcFrequencyFigure(mcBurnInPlot, mcWalk.slice(100), "Discarding first 100 samples")
{
  const thinned = []
  for (let i = 100; i &lt; mcWalk.length; i += 20) thinned.push(mcWalk[i])
  return mcFrequencyFigure(mcThinPlot, thinned, "Keeping only every 20th sample")
}
